  try {
    var result = yield Promise.reject('boom');
    console.log('never:', result);
  } catch (err) {
    console.log('caught in generator:', err);
  }
}
function run(gen) {
  var it = gen();
  function step(err, val) {
    var res;
    if (err) {
      res = it.____(err); // 把錯誤丟回生成器內部的 try/catch
    } else {
      res = it.next(val);
    }
    if (res.done) return;
    res.value.then(
      function (v) { step(null, v); },
      function (e) { step(e); }
    );
  }
  step();
}
run(main);

